insert into public.content_items(id,kind,payload,content_hash) values
('adhkar-waking','lesson','{"grade":"TODO_REVIEW","hint_chips":["لأنه أعطانا يوماً جديداً نعيشه","لأن النوم كان مريحاً","لأن الصباح جميل"],"hint_chips_ready":false,"id":"adhkar-waking","meaning_older":"حين تصحو تشكر الله على يوم جديد أعطاك إياه. وفي الذكر معنى أبعد: كما أيقظك اليوم بعد نومك، يبعث الناس يوم القيامة بعد موتهم — فالرجوع إليه في الحالين.","meaning_young":"أول ما تستيقظ من النوم، تشكر الله. أنت كنت نائماً لا تعرف شيئاً عن الدنيا، ثم فتحت عينيك من جديد — وهذه نعمة من الله.","pack":"adhkar","pose":"standing","question":"لماذا نشكر الله حين نستيقظ؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"morning","scene_mode":"generated","situation":"الاستيقاظ","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَمَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","top_layer":{"image":"top-waking.png","title":"عند الاستيقاظ من النوم نقول:"}}'::jsonb,'1eed524a8ae50f169eb8a737f1b72cf1647c7aa6709323a186ac39ea4b488217'),
('adhkar-dressing','lesson','{"grade":"TODO_REVIEW","hint_chips":["أن الله هو الذي رزقنا إياه","أن الثوب غالي الثمن","أن لوننا المفضل جميل"],"hint_chips_ready":false,"id":"adhkar-dressing","meaning_older":"تشكر الله على ثوب يسترك ويدفئك. وتتذكر أنك لم تحصل عليه بقوتك وحدك: الله هو الذي يسّره لك ورزقك إياه، وغيرك قد لا يجد مثله.","meaning_young":"حين تلبس ثوبك تشكر الله. فهو الذي أعطاك إياه، وأنت لم تصنعه بنفسك.","pack":"adhkar","pose":"standing","question":"ماذا نتذكّر حين نلبس ثوبنا؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"home","scene_mode":"generated","situation":"لبس الثياب","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّة","top_layer":{"image":null,"title":"عند لبس الثياب نقول:"}}'::jsonb,'706c9b60134ebb4a0c136b9c365d1cedca07b7b3e7c2dc51a2ecf6991c6abe73'),
('adhkar-food-before','lesson','{"grade":"TODO_REVIEW","hint_chips":["أن يجعل الطعام خيراً ونافعاً لنا","أن يكون الطعام لذيذاً","أن نأكل كثيراً"],"hint_chips_ready":false,"id":"adhkar-food-before","meaning_older":"قبل الطعام تطلب من الله أن يبارك لك فيه: أن يكون نافعاً لجسمك ومعيناً لك على الخير. وتطلب منه أن ينجّيك ويحفظك. ثم تبدأ أكلك ذاكراً اسم من رزقك إياه.","meaning_young":"قبل أن تأكل، تسأل الله أن يجعل طعامك خيراً لك. وتطلب منه أن يحفظك ويحميك، ثم تبدأ أكلك ذاكراً اسمه.","pack":"adhkar","pose":"sitting","question":"ماذا نطلب من الله قبل الطعام؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"food","scene_mode":"generated","situation":"الطعام","source":"TODO_REVIEW","text":"اللَّهُمَّ بَارِكْ لَنَا فِيمَا رَزَقْتَنَا، وَقِنَا عَذَابَ النَّارِ، بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","top_layer":{"image":null,"title":"قبل الطعام نقول:"}}'::jsonb,'780d3b20f7b795ccced43dc159590604b47e3ed6a767eda0583520b0e67d55ec'),
('adhkar-food-after','lesson','{"grade":"TODO_REVIEW","hint_chips":["نعمة أن جعلنا مسلمين","نعمة الأصدقاء","نعمة البيت"],"hint_chips_ready":false,"id":"adhkar-food-after","meaning_older":"بعد الطعام تشكر الله على نعمتين: نعمة الطعام والشراب التي يحتاجها جسمك، ونعمة الهداية إلى دينه وهي أعظم منهما. فالذكر يذكّرك أن أكبر ما أُعطيت ليس ما في الصحن.","meaning_young":"بعد أن تأكل وتشرب، تشكر الله على طعامك وعلى الماء. وتشكره على نعمة أكبر منهما: أن هداك إلى دينه.","pack":"adhkar","pose":"sitting","question":"على أي نعمة نشكر الله في هذا الذكر غير الطعام والشراب؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"food","scene_mode":"generated","situation":"الطعام","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ","top_layer":{"image":null,"title":"بعد الطعام نقول:"}}'::jsonb,'423c88c0621ae610b2a3a9a435213fe9ca7734668cba3431b6d3bf7383d136d3')
